	DiscountPercent int       `json:"discount_percent"`
	// StartedAt is when the subscription began; its billing periods are counted from it.
	StartedAt          time.Time  `json:"started_at"`
	CurrentPeriodStart time.Time  `json:"current_period_start"`
	CurrentPeriodEnd   time.Time  `json:"current_period_end"`
	TrialEnd           *time.Time `json:"trial_end,omitempty"`
	CancelAtPeriodEnd  bool       `json:"cancel_at_period_end"`
	CanceledAt         *time.Time `json:"canceled_at,omitempty"`
	CreatedAt          time.Time  `json:"created_at"`
}

// Line is one line of an invoice. A negative UnitAmount is a credit.
type Line struct {
	Description string `json:"description"`
	Quantity    int64  `json:"quantity"`
	UnitAmount  int64  `json:"unit_amount"`
}

// Amount is the line's quantity times its unit amount.
func (l Line) Amount() int64 { return l.Quantity * l.UnitAmount }

// InvoiceStatus is an invoice's state.
type InvoiceStatus string

// Invoice states.
const (
	InvoiceOpen InvoiceStatus = "open"
	InvoicePaid InvoiceStatus = "paid"
	InvoiceVoid InvoiceStatus = "void"
)

// Invoice is a bill to a customer.
type Invoice struct {
	ID              string         `json:"id"`
	OrgID           string         `json:"org_id"`
	CustomerID      string         `json:"customer_id"`
	SubscriptionID  string         `json:"subscription_id,omitempty"`
	Currency        money.Currency `json:"currency"`
	Lines           []Line         `json:"lines"`
	DiscountPercent int            `json:"discount_percent"`
	TaxRateBP       int            `json:"tax_rate_bp"`
	Status          InvoiceStatus  `json:"status"`
	PeriodStart     *time.Time     `json:"period_start,omitempty"`
	PeriodEnd       *time.Time     `json:"period_end,omitempty"`
	CreatedAt       time.Time      `json:"created_at"`
	PaidAt          *time.Time     `json:"paid_at,omitempty"`
	VoidedAt        *time.Time     `json:"voided_at,omitempty"`
}

// PaymentStatus is a payment attempt's result.
type PaymentStatus string

// Payment results.
const (
	PaymentSucceeded PaymentStatus = "succeeded"
	PaymentFailed    PaymentStatus = "failed"
)

// Payment is one attempt to charge an invoice.
type Payment struct {
	ID          string         `json:"id"`
	OrgID       string         `json:"org_id"`
	InvoiceID   string         `json:"invoice_id"`
	Amount      int64          `json:"amount"`
	Currency    money.Currency `json:"currency"`
	Status      PaymentStatus  `json:"status"`
	FailureCode string         `json:"failure_code,omitempty"`
	GatewayRef  string         `json:"gateway_ref,omitempty"`
	CreatedAt   time.Time      `json:"created_at"`
}

// UsageRecord is usage reported for a subscription to a metered plan.
type UsageRecord struct {
	ID             string    `json:"id"`
	OrgID          string    `json:"org_id"`
	SubscriptionID string    `json:"subscription_id"`
	Quantity       int64     `json:"quantity"`
	At             time.Time `json:"at"`
	CreatedAt      time.Time `json:"created_at"`
}

// WebhookEndpoint is a URL of the organization's that receives events.
type WebhookEndpoint struct {
	ID     string   `json:"id"`
	OrgID  string   `json:"org_id"`
	URL    string   `json:"url"`
	Events []string `json:"events"` // event types, or "*" for all
	// Secret signs the deliveries (webhooks.Sign).
	Secret         string    `json:"secret"`
	Enabled        bool      `json:"enabled"`
	DisabledReason string    `json:"disabled_reason,omitempty"`
	CreatedAt      time.Time `json:"created_at"`
}

// Event is something that happened in an organization, sent to its webhook endpoints.
type Event struct {
	ID        string          `json:"id"`
	OrgID     string          `json:"org_id"`
	Type      string          `json:"type"`
	Data      json.RawMessage `json:"data"`
	CreatedAt time.Time       `json:"created_at"`
}

// DeliveryStatus is a webhook delivery's state.
type DeliveryStatus string

// Delivery states.
const (
	DeliveryPending   DeliveryStatus = "pending"
	DeliverySucceeded DeliveryStatus = "succeeded"
	DeliveryFailed    DeliveryStatus = "failed"
)

// Delivery is the sending of one event to one endpoint.
type Delivery struct {
	ID             string         `json:"id"`
	OrgID          string         `json:"org_id"`
	EndpointID     string         `json:"endpoint_id"`
	EventID        string         `json:"event_id"`
	Status         DeliveryStatus `json:"status"`
	Attempts       int            `json:"attempts"`
	NextAttemptAt  *time.Time     `json:"next_attempt_at,omitempty"`
	LastAttemptAt  *time.Time     `json:"last_attempt_at,omitempty"`
	ResponseStatus int            `json:"response_status,omitempty"`
	Error          string         `json:"error,omitempty"`
	CreatedAt      time.Time      `json:"created_at"`
}
// Package billing is invoice arithmetic and billing periods. It holds no state.
package billing

import (
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// Totals are the amounts shown on an invoice, in the invoice currency's minor unit.
type Totals struct {
	Subtotal int64 `json:"subtotal"`
	Discount int64 `json:"discount"`
	Tax      int64 `json:"tax"`
	Total    int64 `json:"total"`
}

// Compute returns an invoice's totals: the sum of its lines, the discount (DiscountPercent of the subtotal), and tax at the
// invoice's rate on the subtotal after the discount. The discount and the tax are each rounded half away from zero to a
// whole minor unit.
func Compute(inv store.Invoice) Totals {
	var subtotal int64
	for _, l := range inv.Lines {
		subtotal += l.Amount()
	}
	discount := money.Percent(subtotal, inv.DiscountPercent)
	taxable := subtotal - discount
	tax := money.BasisPoints(taxable, inv.TaxRateBP)
	return Totals{Subtotal: subtotal, Discount: discount, Tax: tax, Total: taxable + tax}
}

// AddInterval returns t moved forward by one billing interval: a month or a year.
func AddInterval(t time.Time, iv store.Interval) time.Time {
	if iv == store.Yearly {
		return t.AddDate(1, 0, 0)
	}
	return t.AddDate(0, 1, 0)
}
// Package money handles amounts of money. An amount is an int64 count of its currency's minor unit (cents for USD), never a
// float.
package money

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// Currency is an ISO 4217 currency code.
type Currency string

// The currencies Tally bills in.
const (
	USD Currency = "USD"
	EUR Currency = "EUR"
	GBP Currency = "GBP"
	JPY Currency = "JPY"
	KWD Currency = "KWD"
)

var symbols = map[Currency]string{USD: "$", EUR: "€", GBP: "£", JPY: "¥", KWD: "KWD "}

// Valid reports whether c is a currency Tally bills in.
func (c Currency) Valid() bool {
	_, ok := symbols[c]
	return ok
}

// ErrInvalidAmount is returned for an amount that cannot be read.
var ErrInvalidAmount = errors.New("invalid amount")

// ParseMajor reads an amount a person typed in major units ("12.50", "7") and returns it in minor units.
func ParseMajor(s string, c Currency) (int64, error) {
	if !c.Valid() {
		return 0, fmt.Errorf("%w: unknown currency %q", ErrInvalidAmount, c)
	}
	s = strings.TrimSpace(s)
	whole, frac, hasDot := strings.Cut(s, ".")
	if whole == "" || (hasDot && frac == "") || len(frac) > 2 {
		return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
	}
	for _, r := range whole + frac {
		if r < '0' || r > '9' {
			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
		}
	}
	for len(frac) < 2 {
		frac += "0"
	}
	n, err := strconv.ParseInt(whole+frac, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
	}
	return n, nil
}

// Format renders an amount for people: "$1,234.50", "-€0.99".
func Format(amount int64, c Currency) string {
	sign := ""
	if amount < 0 {
		sign, amount = "-", -amount
	}
	whole, frac := amount/100, amount%100
	return fmt.Sprintf("%s%s%s.%02d", sign, symbols[c], group(whole), frac)
}

// group writes n with a comma between each group of three digits.
func group(n int64) string {
	s := strconv.FormatInt(n, 10)
	var b strings.Builder
	for i, r := range s {
		if i > 0 && (len(s)-i)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteRune(r)
	}
	return b.String()
}

// Percent returns pct percent of amount, rounded half away from zero to a whole minor unit.
func Percent(amount int64, pct int) int64 { return divRound(amount*int64(pct), 100) }

// BasisPoints returns bp basis points (hundredths of a percent) of amount, rounded half away from zero.
func BasisPoints(amount int64, bp int) int64 { return divRound(amount*int64(bp), 10000) }

// divRound divides and rounds half away from zero.
func divRound(num, den int64) int64 {
	if (num < 0) != (den < 0) {
		return -((abs(num) + abs(den)/2) / abs(den))
	}
	return (abs(num) + abs(den)/2) / abs(den)
}

func abs(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}
package api

import (
	"errors"
	"fmt"
	"net/http"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// planView is a plan with its price in major units ("12.50") and formatted for people ("$12.50").
type planView struct {
	store.Plan
	Price          string `json:"price"`
	PriceFormatted string `json:"price_formatted"`
}

func viewPlan(p store.Plan) planView {
	return planView{Plan: p, Price: fmt.Sprintf("%.2f", float64(p.UnitAmount)/100), PriceFormatted: money.Format(p.UnitAmount, p.Currency)}
}

func (s *Server) listPlans(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	items := []planView{}
	for _, pl := range s.store.Plans(p.OrgID) {
		items = append(items, viewPlan(pl))
	}
	writeJSON(w, http.StatusOK, list{Items: items})
}

// createPlan takes the price in major units, as a string ("12.50"), the way people type it.
func (s *Server) createPlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Name      string          `json:"name"`
		Currency  money.Currency  `json:"currency"`
		Price     string          `json:"price"`
		Interval  store.Interval  `json:"interval"`
		UsageType store.UsageType `json:"usage_type"`
		TrialDays int             `json:"trial_days"`
	}
	if !decode(w, r, &in) {
		return
	}
	amount, err := money.ParseMajor(in.Price, in.Currency)
	if err != nil {
		if errors.Is(err, money.ErrInvalidAmount) {
			writeError(w, http.StatusUnprocessableEntity, "invalid_amount", err.Error())
			return
		}
		s.storeError(w, err)
		return
	}
	pl, err := s.store.CreatePlan(store.Plan{OrgID: p.OrgID, Name: in.Name, Currency: in.Currency, UnitAmount: amount, Interval: in.Interval,
		UsageType: in.UsageType, TrialDays: in.TrialDays}, s.clock.Now())
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, viewPlan(pl))
}

func (s *Server) getPlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	pl, ok := s.store.Plan(p.OrgID, r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such plan")
		return
	}
	writeJSON(w, http.StatusOK, viewPlan(pl))
}

func (s *Server) updatePlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Name   *string `json:"name"`
		Active *bool   `json:"active"`
	}
	if !decode(w, r, &in) {
		return
	}
	pl, err := s.store.UpdatePlan(p.OrgID, r.PathValue("id"), func(pl *store.Plan) error {
		if in.Name != nil {
			pl.Name = *in.Name
		}
		if in.Active != nil {
			pl.Active = *in.Active
		}
		return nil
	})
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, viewPlan(pl))
}
# Tally

Tally is a billing platform for SaaS companies. Each organization (a tenant) keeps its customers, sells them plans, bills
them through subscriptions and invoices, takes payments through the payment gateway, and receives webhooks about what
happened. Its own staff work in the organization as members with roles. Go standard library only.

## Layout

| Package | What it does |
|---|---|
| `internal/store` | Everything Tally knows, in memory, safe for concurrent use. Every object belongs to one organization; methods that take an `orgID` only see that organization's objects. |
| `internal/money` | Currencies and amounts. Amounts are `int64` counts of the currency's minor unit (cents for USD), never floats. |
| `internal/billing` | Invoice arithmetic (`Compute`) and billing periods (`AddInterval`). No state. |
| `internal/payments` | Charges invoices through the payment `Gateway`; `Fake` is the gateway of tests and the demo server. |
| `internal/subscriptions` | Starts, changes, cancels and renews subscriptions (`RenewDue` runs every 30 seconds in the server). |
| `internal/webhooks` | Checks endpoint URLs, records events (`Publish`) and sends deliveries (`RunDue`, every 30 seconds). |
| `internal/mail` | Email goes through a `Sender`; `Outbox` keeps messages (tests, demo server). |
| `internal/jobs` | The background job runner. |
| `internal/reports` | The dashboard's reports. |
| `internal/snapshot` | Saves the store to a JSON file and loads it back, migrating files written by older versions. |
| `internal/auth` | Who a request is and what they may do. |
| `internal/api` | The JSON HTTP API, version 1. |
| `internal/apitest` | Builds a whole service with fakes (clock, gateway, outbox, webhook receivers, DNS) and two organizations, for tests. |
| `cmd/tally` | The server: `go run ./cmd/tally -addr :8080 -data tally.json` (prints a demo API key on first start). |

## API conventions

- Every request under `/v1/` sends an API key: `Authorization: Bearer tly_...`. A key acts as the member who created it, in
  that member's organization, with the member's current role (`owner`, `admin`, `billing`, `member`, `viewer`).
- Bodies are JSON. Errors are `{"error": "<code>", "message": "<for people>"}` with the matching status. Another
  organization's object is answered exactly like one that does not exist: 404 `not_found`.
- Lists are `{"items": [...], "next_cursor": "..."}`, oldest first; `?limit=` (1 to 100, default 20) and `?cursor=` page
  through them. `next_cursor` is absent on the last page.
- Times are RFC 3339 in UTC. Amounts are integers in the currency's minor unit; fields ending in `_formatted` are for people.
- Every response carries an `X-Request-Id` (the caller's, when it sent a sensible one).

## Working on Tally

- Run the tests with `go test ./...`. Use `apitest.New(t)` for anything that goes through the API; move time with
  `e.Clock`, never with sleeps.
- The admin tool and the integration test suite (both kept in other repositories) use the exported identifiers of these
  packages and the HTTP API. Keep existing exported names, signatures and API fields working; adding new ones is fine.

