// TiersMode says how a tiered plan prices usage.
type TiersMode string

// Tier modes.
const (
	// Graduated prices each unit at the unit amount of the tier it falls in.
	Graduated TiersMode = "graduated"
	// Volume prices every unit at the unit amount of the one tier the total usage falls in.
	Volume TiersMode = "volume"
)

// Tier is one band of a metered plan's usage. Its amounts are in minor units.
type Tier struct {
	// UpTo is the last quantity in the tier, inclusive. Nil means no upper limit, which only the last tier has.
	UpTo       *int64 `json:"up_to"`
	UnitAmount int64  `json:"unit_amount"`
	FlatAmount int64  `json:"flat_amount"`
}

// Plan is something an organization sells to its customers.
type Plan struct {
	ID         string         `json:"id"`
	OrgID      string         `json:"org_id"`
	Name       string         `json:"name"`
	Currency   money.Currency `json:"currency"`
	UnitAmount int64          `json:"unit_amount"` // minor units; a tiered plan does not use it
	Interval   Interval       `json:"interval"`
	UsageType  UsageType      `json:"usage_type"`
	TrialDays  int            `json:"trial_days"`
	// TiersMode and Tiers are set on a tiered metered plan, which prices usage with its tiers instead of UnitAmount.
	TiersMode TiersMode `json:"tiers_mode,omitempty"`
	Tiers     []Tier    `json:"tiers,omitempty"`
	Active    bool      `json:"active"`
	CreatedAt time.Time `json:"created_at"`
}

