// tierIn is a tier as the API takes it: amounts in major units, as strings ("12.50"); flat_amount may be left out.
type tierIn struct {
	UpTo       *json.Number `json:"up_to"`
	UnitAmount string       `json:"unit_amount"`
	FlatAmount string       `json:"flat_amount"`
}

// parseTiers reads tiers in major units. Any amount that is not a plain non-negative amount, or an up_to that is not a whole
// number, is an invalid tier.
func parseTiers(in []tierIn, c money.Currency) ([]store.Tier, error) {
	tiers := []store.Tier{}
	for _, t := range in {
		var tier store.Tier
		if t.UpTo != nil {
			n, err := strconv.ParseInt(t.UpTo.String(), 10, 64)
			if err != nil {
				return nil, fmt.Errorf("%w: up_to %q is not a whole number", store.ErrInvalidTiers, t.UpTo.String())
			}
			tier.UpTo = &n
		}
		var err error
		if tier.UnitAmount, err = money.ParseMajor(t.UnitAmount, c); err != nil {
			return nil, fmt.Errorf("%w: unit_amount: %v", store.ErrInvalidTiers, err)
		}
		if t.FlatAmount != "" {
			if tier.FlatAmount, err = money.ParseMajor(t.FlatAmount, c); err != nil {
				return nil, fmt.Errorf("%w: flat_amount: %v", store.ErrInvalidTiers, err)
			}
		}
		tiers = append(tiers, tier)
	}
	return tiers, nil
}

// createPlan takes the price in major units, as a string ("12.50"), the way people type it. A tiered plan takes tiers
// instead, and no price.
func (s *Server) createPlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Name      string          `json:"name"`
		Currency  money.Currency  `json:"currency"`
		Price     string          `json:"price"`
		Interval  store.Interval  `json:"interval"`
		UsageType store.UsageType `json:"usage_type"`
		TrialDays int             `json:"trial_days"`
		TiersMode store.TiersMode `json:"tiers_mode"`
		Tiers     []tierIn        `json:"tiers"`
	}
	if !decode(w, r, &in) {
		return
	}
	pl := store.Plan{OrgID: p.OrgID, Name: in.Name, Currency: in.Currency, Interval: in.Interval, UsageType: in.UsageType, TrialDays: in.TrialDays}
	if in.TiersMode != "" || len(in.Tiers) > 0 {
		tiers, err := parseTiers(in.Tiers, in.Currency)
		if err != nil {
			writeError(w, http.StatusUnprocessableEntity, "invalid_tiers", err.Error())
			return
		}
		pl.TiersMode, pl.Tiers = in.TiersMode, tiers
	} else {
		amount, err := money.ParseMajor(in.Price, in.Currency)
		if err != nil {
			if errors.Is(err, money.ErrInvalidAmount) {
				writeError(w, http.StatusUnprocessableEntity, "invalid_amount", err.Error())
				return
			}
			s.storeError(w, err)
			return
		}
		pl.UnitAmount = amount
	}
	created, err := s.store.CreatePlan(pl, s.clock.Now())
	if errors.Is(err, store.ErrInvalidTiers) {
		writeError(w, http.StatusUnprocessableEntity, "invalid_tiers", err.Error())
		return
	}
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, viewPlan(created))
}

