func TestTieredPlans(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	upTo := func(n int64) *int64 { return &n }
	tiers := []Tier{{UpTo: upTo(10), UnitAmount: 100}, {UnitAmount: 50, FlatAmount: 300}}
	p, err := s.CreatePlan(Plan{OrgID: a.ID, Name: "Usage", Currency: money.USD, Interval: Monthly, UsageType: Metered, TiersMode: Graduated, Tiers: tiers}, t0)
	if err != nil || p.UnitAmount != 0 || p.TiersMode != Graduated || len(p.Tiers) != 2 {
		t.Fatalf("CreatePlan = %+v, %v", p, err)
	}
	tiers[0].UnitAmount = 1 // the caller's slice is not the plan's
	if got, _ := s.Plan(a.ID, p.ID); got.Tiers[0].UnitAmount != 100 {
		t.Fatalf("stored tiers changed with the caller's slice: %+v", got.Tiers)
	}
	got, _ := s.Plan(a.ID, p.ID)
	*got.Tiers[0].UpTo = 99 // nor with a plan returned by Plan
	if again, _ := s.Plan(a.ID, p.ID); *again.Tiers[0].UpTo != 10 {
		t.Fatalf("stored up_to changed: %+v", again.Tiers)
	}

	bad := map[string]Plan{
		"licensed":          {UsageType: Licensed, TiersMode: Graduated, Tiers: tiers},
		"no mode":           {UsageType: Metered, Tiers: tiers},
		"unknown mode":      {UsageType: Metered, TiersMode: "flat", Tiers: tiers},
		"mode without tier": {UsageType: Metered, TiersMode: Volume},
		"tiers without mode": {UsageType: Metered, Tiers: tiers},
		"last tier limited": {UsageType: Metered, TiersMode: Volume, Tiers: []Tier{{UpTo: upTo(10)}}},
		"unlimited middle":  {UsageType: Metered, TiersMode: Volume, Tiers: []Tier{{UnitAmount: 1}, {UnitAmount: 2}}},
		"not ascending":     {UsageType: Metered, TiersMode: Volume, Tiers: []Tier{{UpTo: upTo(10)}, {UpTo: upTo(5)}, {}}},
		"repeated up_to":    {UsageType: Metered, TiersMode: Volume, Tiers: []Tier{{UpTo: upTo(10)}, {UpTo: upTo(10)}, {}}},
		"zero up_to":        {UsageType: Metered, TiersMode: Volume, Tiers: []Tier{{UpTo: upTo(0)}, {}}},
		"negative unit":     {UsageType: Metered, TiersMode: Volume, Tiers: []Tier{{UpTo: upTo(10), UnitAmount: -1}, {}}},
		"negative flat":     {UsageType: Metered, TiersMode: Volume, Tiers: []Tier{{UpTo: upTo(10)}, {FlatAmount: -1}}},
	}
	for name, in := range bad {
		in.OrgID, in.Name, in.Currency, in.Interval = a.ID, "Bad", money.USD, Monthly
		if _, err := s.CreatePlan(in, t0); !errors.Is(err, ErrInvalidTiers) || !errors.Is(err, ErrInvalid) {
			t.Errorf("%s: CreatePlan err = %v, want ErrInvalidTiers", name, err)
		}
	}

	if up, err := s.UpdatePlan(a.ID, p.ID, func(p *Plan) error { p.Tiers, p.TiersMode = nil, Volume; return nil }); err != nil ||
		up.TiersMode != Graduated || len(up.Tiers) != 2 {
		t.Fatalf("UpdatePlan = %+v, %v (the tiers must not change)", up, err)
	}
}
EOF
